// Import catalog entries into a THROWAWAY Postgres (node-2 agent cluster only) and/or a SQLite index file, idempotently.
//   npx tsx scripts/cyrus/library-import.ts --entries entries2-staged-cc0.jsonl [--dry-run] [--pg] [--extras] [--sqlite f.db] [--twice] [--bench] [--out r.json]
//   --pg      write into DATABASE_URL (refused unless it is a node-2 throwaway database 127.0.0.1:5433/wt_*)
//   --extras  create pg_trgm + the GIN indexes of lib/cyrus/library/backend/pg-extras.ts first
//   --twice   run the real import twice (the second run must write nothing: idempotency)
//   --bench   time the situation + broad queries against the Postgres index after the import
// Prints counts and timings as JSON. No model calls, no network apart from the local database.
import { writeFileSync } from "node:fs";
import { PrismaClient } from "@prisma/client";
import { entryHash, createPgCatalog, prismaSql } from "../../lib/cyrus/library/backend/pg";
import { PG_EXTRAS_SQL } from "../../lib/cyrus/library/backend/pg-extras";
import { fileLines, importEntries } from "../../lib/cyrus/library/backend/importer";
import { createSqliteCatalogIndex } from "../../lib/cyrus/library/v2/sqlite-index";
import { catalogSearch } from "../../lib/cyrus/library/v2/tools";
import { BROAD_QUERIES, SITUATION_QUERIES } from "./library-queries";

const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : undefined; };
const has = (k: string) => process.argv.includes(k);
const THROWAWAY = /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:5433\/wt_[a-z0-9_]+(\?.*)?$/;

async function main() {
  const file = arg("--entries");
  if (!file) { console.error("usage: library-import.ts --entries f.jsonl [--dry-run] [--pg] [--extras] [--sqlite f.db] [--twice] [--bench] [--out r.json]"); process.exit(2); }
  const out: Record<string, unknown> = { file, at: new Date().toISOString() };
  let prisma: PrismaClient | null = null;
  let pg: ReturnType<typeof createPgCatalog> | null = null;
  if (has("--pg")) {
    if (!THROWAWAY.test(process.env.DATABASE_URL ?? "")) { console.error("refusing: DATABASE_URL is not a node-2 throwaway database"); process.exit(3); }
    prisma = new PrismaClient();
    pg = createPgCatalog(prismaSql(prisma), { fuzzy: true, batch: 500 });
    if (has("--extras")) { const t = Date.now(); for (const s of PG_EXTRAS_SQL) await prisma.$executeRawUnsafe(s); out.extrasMs = Date.now() - t; }
  }
  const sink = pg ? { upsertWithReport: pg.upsertWithReport, existingHashes: pg.existingHashes } : undefined;
  out.dryRun = await importEntries(fileLines(file), { sink, dryRun: true, entryHash });
  console.log("dry-run", JSON.stringify(out.dryRun));
  if (!has("--dry-run")) {
    const sqlite = arg("--sqlite") ? await createSqliteCatalogIndex(arg("--sqlite")!) : undefined;
    out.real = await importEntries(fileLines(file), { sink, index: sqlite, dryRun: false });
    console.log("real", JSON.stringify(out.real));
    if (has("--twice")) {
      out.second = await importEntries(fileLines(file), { sink, dryRun: false });
      console.log("second", JSON.stringify(out.second));
    }
    if (sqlite) { out.sqliteSize = await sqlite.size(); sqlite.close(); }
  }
  if (pg && has("--bench")) {
    const rows: unknown[] = [];
    for (const q of [...SITUATION_QUERIES, ...BROAD_QUERIES, "wodden dor"]) {
      const times: number[] = [];
      let n = 0, top = "";
      for (let i = 0; i < 3; i++) {
        const t = process.hrtime.bigint();
        const r = await catalogSearch({ query: q, limit: 8 }, { index: pg.index, plan: "all", game: null, proprietaryCleared: true });
        times.push(Number(process.hrtime.bigint() - t) / 1e6);
        const b = JSON.parse(r.content) as { n?: number; rows?: { t: string }[] }; n = b.n ?? 0; top = b.rows?.[0]?.t ?? "";
      }
      times.sort((a, b) => a - b);
      rows.push({ q, medianMs: +times[1].toFixed(1), maxMs: +times[2].toFixed(1), n, top });
      console.log(`pg ${JSON.stringify(q).padEnd(34)} median ${times[1].toFixed(1)} ms  max ${times[2].toFixed(1)} ms  n ${n}  top ${top}`);
    }
    out.pgBench = rows;
    const t = Date.now(); const found = await pg.admin.find("wooden door"); out.adminFindMs = Date.now() - t; out.adminFindN = found.length;
    out.counts = await pg.admin.counts();
  }
  if (prisma) await prisma.$disconnect();
  if (arg("--out")) writeFileSync(arg("--out")!, JSON.stringify(out, null, 1));
}
main().catch((e) => { console.error(e); process.exit(1); });

