// The Postgres search indexes Prisma's schema cannot express (kept in ONE place: the migration file
// prisma/manual-migrations/2026-10-10-cyrus-library-backend.sql repeats them verbatim, and the throwaway-DB test
// applies them from here). All IF NOT EXISTS: re-running is harmless.
//   pg_trgm + (entry->>'title')           typo fallback (similarity on titles)
//   to_tsvector('simple', "searchText")   admin full-text find
// EXPRESSION indexes on purpose: measured on node-2, `prisma db push` (what promote-production runs) DROPS a GIN index
// on a plain column it does not know ("searchText" gin_trgm_ops was dropped), but leaves expression indexes alone.
export const PG_EXTRAS_SQL: readonly string[] = [
  `CREATE EXTENSION IF NOT EXISTS pg_trgm`,
  `CREATE INDEX IF NOT EXISTS "CyrusCatalogEntry_title_trgm_idx" ON "CyrusCatalogEntry" USING GIN ((entry->>'title') gin_trgm_ops)`,
  `CREATE INDEX IF NOT EXISTS "CyrusCatalogEntry_searchText_fts_idx" ON "CyrusCatalogEntry" USING GIN (to_tsvector('simple', "searchText"))`,
];
};

const bump = (m: Record<string, number>, k: string) => { m[k] = (m[k] ?? 0) + 1; };

export async function importEntries(lines: Iterable<string> | AsyncIterable<string>, opts: { sink?: ImportSink; index?: CatalogIndex; dryRun: boolean; batch?: number; includeCcBy?: boolean; entryHash?: (e: CatalogEntry) => string }): Promise<ImportReport> {
  const t0 = Date.now();
  const rep: ImportReport = { dryRun: opts.dryRun, lines: 0, valid: 0, invalid: 0, skippedCcBy: 0, duplicateIds: 0, byKind: {}, byTier: {}, byStatus: {}, inserted: 0, updated: 0, unchanged: 0, terms: 0, errors: [], ms: 0 };
  const seen = new Set<string>();
  const batchSize = Math.max(1, opts.batch ?? 1000);
  let pending: CatalogEntry[] = [];
  const flush = async () => {
    if (!pending.length) return;
    const b = pending; pending = [];
    if (opts.dryRun) {
      if (opts.sink?.existingHashes && opts.entryHash) {
        const have = await opts.sink.existingHashes(b.map((e) => e.id));
        for (const e of b) { const h = have.get(e.id); if (h === undefined) rep.inserted++; else if (h === opts.entryHash(e)) rep.unchanged++; else rep.updated++; }
      } else rep.inserted += b.length;
      return;
    }
    if (opts.sink) { const r = await opts.sink.upsertWithReport(b); rep.inserted += r.inserted; rep.updated += r.updated; rep.unchanged += r.unchanged; rep.terms += r.terms; }
    if (opts.index) await opts.index.upsert(b);
  };
  for await (const raw of lines as AsyncIterable<string>) {
    const line = raw.trim();
    if (!line) continue;
    rep.lines++;
    let parsed: unknown;
    try { parsed = JSON.parse(line); } catch { rep.invalid++; if (rep.errors.length < 20) rep.errors.push({ line: rep.lines, error: "not JSON" }); continue; }
    const v = validateCatalogEntry(parsed);
    if (!v.ok) { rep.invalid++; if (rep.errors.length < 20) rep.errors.push({ line: rep.lines, error: v.errors.map((e) => `${e.path}: ${e.message}`).join("; ").slice(0, 300) }); continue; }
    const e = v.entry;
    if (e.licence.tier === "cc-by" && !opts.includeCcBy) { rep.skippedCcBy++; continue; }
    if (seen.has(e.id)) { rep.duplicateIds++; continue; }
    seen.add(e.id);
    rep.valid++; bump(rep.byKind, e.kind); bump(rep.byTier, e.licence.tier); bump(rep.byStatus, e.status);
    pending.push(e);
    if (pending.length >= batchSize) await flush();
  }
  await flush();
  rep.ms = Date.now() - t0;
  return rep;
}

/** Lines of a file without loading it whole (node:readline). SERVER ONLY. */
export async function* fileLines(file: string): AsyncIterable<string> {
  const { createReadStream } = await import("node:fs");
  const { createInterface } = await import("node:readline");
  const rl = createInterface({ input: createReadStream(file, { encoding: "utf8" }), crlfDelay: Infinity });
  for await (const l of rl) yield l;
}
