// The ONE door to Cyrus' own database. Cyrus code imports `cyrusDb` from here (never lib/db). It resolves through the host
// registry on every use, so setHost() (tests, a standalone deployment) takes effect immediately. Typed as CyrusDb: only
// Cyrus' own tables plus $transaction/raw SQL exist on it; platform tables must go through the host's methods.
import { getHost } from "./host";
import type { CyrusDb } from "./host";

export type { CyrusDb };
export const cyrusDb: CyrusDb = new Proxy({} as CyrusDb, {
  get(_t, prop) {
    const c = getHost().db as unknown as Record<PropertyKey, unknown>;
    const v = c[prop];
    return typeof v === "function" ? (v as (...a: unknown[]) => unknown).bind(c) : v;
  },
  set(_t, prop, value) { (getHost().db as unknown as Record<PropertyKey, unknown>)[prop] = value; return true; },
  has(_t, prop) { return prop in (getHost().db as object); },
});
// LibraryStore: the bytes side of the asset library, on the ObjectStore contract (./objects.ts).
//   originals    a contribution / copied original lives in the object store at sha256/<entry id>; a staged asset is
//                read from the READ-ONLY staging volume (path-confined, sha256-checked). Folder kinds (ambientCG /
//                Poly Haven PBR sets, HDRIs, decals) have no single original: their id is the upstream zip hash, so
//                they are served as the deterministic bundle@1 derivative instead.
//   derivatives  lazily generated by ./derive.ts recipes on first request, cached content-addressed, recorded in
//                LibraryRecords.derivatives (last use tracked for retention).
//   caps         per-kind original caps (checked on the file size before reading) + per-recipe output caps.
//   retention    sweep(): derivative rows unused for RETENTION.derivativeUnusedDays are dropped (objects with no
//                other reference deleted: they regenerate on demand); a REMOVED community asset's own object is
//                deleted after RETENTION.removedGraceDays. Staged files are never touched. Projects that used an
//                asset keep their own copy (CyrusProjectAsset), so nothing here can break an existing mod.
//   serving      canServe(): status, variant and plan/licence rules; raw audio is NEVER served (preview-ogg only),
//                the proprietary library never as an original and only once cleared.
// SERVER ONLY. HOST SEAM: no Nxeon imports.
import path from "node:path";
import { promises as fsp } from "node:fs";
import { access } from "../v2/tools";
import type { CatalogEntry, CatalogKind } from "../v2/entry";
import type { CatalogStore } from "../v2/pipeline";
import { BUNDLE_EXT, isFolderEntry, RECIPE_MIME, recipesFor, runRecipe, type DeriveTools, type RecipeId } from "./derive";
import { keyOf, type LibraryObjectStore, type StagingSource } from "./objects";
import type { LibraryRecords } from "./records";
import type { Variant } from "./signed-url";

const MB = 1024 * 1024;
export const ORIGINAL_MAX_BYTES: Readonly<Record<CatalogKind, number>> = {
  model: 96 * MB, "texture-set": 160 * MB, texture: 32 * MB, sprite: 8 * MB, hdri: 160 * MB, decal: 64 * MB, sound: 48 * MB, music: 96 * MB,
  flipbook: 64 * MB, "particle-texture": 16 * MB, "animation-clip": 96 * MB, "animated-model": 96 * MB, "motion-preset": 1 * MB, "effect-preset": 1 * MB,
};
export const RETENTION = { derivativeUnusedDays: 30, removedGraceDays: 30 } as const;
const DAY = 86_400_000;

export type Bytes = { ok: true; bytes: Uint8Array; mime: string; from: "object" | "staging" | "cache" | "generated"; tool?: string };
export type Miss = { ok: false; code: string; error: string };

const MIME: Record<string, string> = { png: "image/png", jpg: "image/jpeg", jpeg: "image/jpeg", glb: "model/gltf-binary", gltf: "model/gltf+json", ogg: "audio/ogg", wav: "audio/wav", mp3: "audio/mpeg", json: "application/json", svg: "image/svg+xml" };
export const mimeOf = (e: Pick<CatalogEntry, "tech">) => MIME[e.tech.format.toLowerCase()] ?? "application/octet-stream";

export class LibraryStore {
  private readonly now: () => Date;
  constructor(private readonly o: { objects: LibraryObjectStore; staging: StagingSource | null; records: LibraryRecords; tools: DeriveTools; now?: () => Date }) {
    this.now = o.now ?? (() => new Date());
  }

  /** The original bytes of a single-file entry (object store first, then the staged file). */
  async original(e: CatalogEntry): Promise<Bytes | Miss> {
    if (isFolderEntry(e)) return { ok: false, code: "folder", error: "a folder entry has no single original; use bundle@1" };
    const cap = ORIGINAL_MAX_BYTES[e.kind];
    const key = keyOf(e.id);
    const size = await this.o.objects.size(key);
    if (size != null) {
      if (size > cap) return { ok: false, code: "too_large", error: `${size} bytes is over the ${cap}-byte cap` };
      const b = await this.o.objects.get(key);
      if (b) return { ok: true, bytes: b, mime: mimeOf(e), from: "object" };
    }
    if (!this.o.staging) return { ok: false, code: "missing", error: "no stored copy and no staging volume" };
    const r = await this.o.staging.read(e.provenance.path, e.id, cap);
    return r.ok ? { ok: true, bytes: r.bytes, mime: mimeOf(e), from: "staging" } : { ok: false, code: r.code, error: r.error };
  }

  /** Copy a staged original into the object store (the owner's "make it self-contained" step; never moves the file). */
  async persistOriginal(e: CatalogEntry): Promise<{ ok: true; key: string; created: boolean } | Miss> {
    const key = keyOf(e.id);
    if (await this.o.objects.has(key)) return { ok: true, key, created: false };
    const b = await this.original(e);
    if (!b.ok) return b;
    return { ok: true, key: await this.o.objects.put(b.bytes), created: true };
  }

  private async stagedFile(rel: string, maxBytes: number): Promise<Uint8Array | null> {
    if (!this.o.staging) return null;
    const r = await this.o.staging.resolve(rel);
    if (!r.ok || r.size > maxBytes) return null;
    return fsp.readFile(r.path);
  }
  private async stagedDir(rel: string): Promise<string[]> { return this.o.staging ? this.o.staging.listDir(rel) : []; }

  /** Where a thumbnail comes from (see ./derive.ts): the PNG itself, a sibling image, or the folder's preview / colour map. */
  async thumbSource(e: CatalogEntry): Promise<{ bytes: Uint8Array; ext: "png" | "jpg" } | null> {
    const fmt = e.tech.format.toLowerCase();
    const flat = e.kind === "sprite" || e.kind === "texture" || e.kind === "decal" || e.kind === "flipbook" || e.kind === "particle-texture";
    if (flat && (fmt === "png" || fmt === "jpg" || fmt === "jpeg")) { const b = await this.original(e); return b.ok ? { bytes: b.bytes, ext: fmt === "png" ? "png" : "jpg" } : null; }
    const p = e.provenance.path;
    if (!p) return null;
    if (e.kind === "model" || e.kind === "animated-model") {
      const sib = p.replace(/\.[a-z0-9]+$/i, ".png");
      const b = sib !== p ? await this.stagedFile(sib, 16 * MB) : null;
      return b ? { bytes: b, ext: "png" } : null;
    }
    if (isFolderEntry(e)) {
      const names = await this.stagedDir(p);
      const base = path.basename(p);
      const pick = (e.kind === "flipbook" ? names.find((n) => /\.png$/i.test(n)) : undefined) ?? names.find((n) => n === `${base}.png`) ?? names.find((n) => /_(color|basecolor|albedo|diff(use)?)\.(jpe?g|png)$/i.test(n)) ?? names.find((n) => /_tonemapped\.(jpe?g|png)$/i.test(n));
      if (!pick) return null;
      const b = await this.stagedFile(`${p}/${pick}`, 64 * MB);
      return b ? { bytes: b, ext: /\.png$/i.test(pick) ? "png" : "jpg" } : null;
    }
    return null;
  }

  /** The folder's bundle files (images + MaterialX), total capped at the kind's original cap. */
  async folder(e: CatalogEntry): Promise<{ name: string; bytes: Uint8Array }[] | null> {
    if (!isFolderEntry(e) || !e.provenance.path) return null;
    const cap = ORIGINAL_MAX_BYTES[e.kind];
    const out: { name: string; bytes: Uint8Array }[] = [];
    let total = 0;
    for (const n of await this.stagedDir(e.provenance.path)) {
      if (!BUNDLE_EXT.test(n)) continue;
      const b = await this.stagedFile(`${e.provenance.path}/${n}`, cap - total);
      if (!b) return null; // over the cap or unreadable: no partial bundles
      total += b.length; out.push({ name: n, bytes: b });
    }
    return out.length ? out : null;
  }

  /** A derivative: cached object, or generated now (deterministic recipe) and cached. */
  async derivative(e: CatalogEntry, recipe: RecipeId): Promise<Bytes | Miss> {
    if (!recipesFor(e).includes(recipe)) return { ok: false, code: "not_available", error: `${recipe} does not apply to a ${e.kind}` };
    const now = this.now();
    const row = await this.o.records.derivatives.get(e.id, recipe);
    if (row) {
      const b = await this.o.objects.get(row.objectKey);
      if (b) { await this.o.records.derivatives.touch(e.id, recipe, now); return { ok: true, bytes: b, mime: RECIPE_MIME[recipe], from: "cache", tool: row.tool }; }
      await this.o.records.derivatives.delete(e.id, recipe); // object gone or corrupt: regenerate
    }
    const r = await runRecipe(recipe, {
      entry: e,
      original: async () => { const b = await this.original(e); return b.ok ? b.bytes : null; },
      thumbSource: () => this.thumbSource(e),
      folder: () => this.folder(e),
    }, this.o.tools);
    if (!r.ok) return { ok: false, code: r.code, error: r.error };
    const objectKey = await this.o.objects.put(r.bytes);
    await this.o.records.derivatives.put({ entryId: e.id, recipe, objectKey, bytes: r.bytes.length, tool: r.tool, createdAt: now, lastUsedAt: now });
    return { ok: true, bytes: r.bytes, mime: RECIPE_MIME[recipe], from: "generated", tool: r.tool };
  }

  /** What a signed URL serves (the caller ran canServe first). */
  async bytesFor(e: CatalogEntry, variant: Variant): Promise<Bytes | Miss> {
    return variant === "original" ? this.original(e) : this.derivative(e, variant);
  }

  /** Takedown: drop every cached derivative of an entry now (stops serving at once; objects shared elsewhere stay). */
  async purgeDerivatives(entryId: string): Promise<number> {
    let n = 0;
    for (const d of await this.o.records.derivatives.forEntry(entryId)) {
      await this.o.records.derivatives.delete(entryId, d.recipe);
      if ((await this.o.records.derivatives.refs(d.objectKey)) === 0) await this.o.objects.delete(d.objectKey);
      n++;
    }
    return n;
  }

  /** Retention sweep (idempotent). Never touches the staging volume or project copies. */
  async sweep(o: { catalog?: CatalogStore; limit?: number } = {}): Promise<{ derivativesDropped: number; objectsDeleted: number; removedOriginalsDeleted: number; bytesFreed: number }> {
    const now = this.now(), limit = o.limit ?? 5000;
    let dropped = 0, deleted = 0, removedDeleted = 0, freed = 0;
    for (const d of await this.o.records.derivatives.unusedSince(new Date(+now - RETENTION.derivativeUnusedDays * DAY), limit)) {
      await this.o.records.derivatives.delete(d.entryId, d.recipe); dropped++;
      if ((await this.o.records.derivatives.refs(d.objectKey)) === 0 && (await this.o.objects.has(d.objectKey))) { await this.o.objects.delete(d.objectKey); deleted++; freed += d.bytes; }
    }
    if (o.catalog) {
      let cursor: string | null = null;
      for (let page = 0; page < 100; page++) {
        const rows: CatalogEntry[] = await o.catalog.listByStatus("removed", cursor, 500);
        if (!rows.length) break;
        cursor = rows[rows.length - 1].id;
        for (const e of rows) {
          if (e.licence.tier !== "user-contributed") continue; // pack assets: the staged file is not ours to delete
          const at = (await this.o.records.log.list({ entryId: e.id, actions: ["takedown"], limit: 1 }))[0]?.at;
          if (!at || +now - +at < RETENTION.removedGraceDays * DAY) continue;
          const key = keyOf(e.id), size = await this.o.objects.size(key);
          if (size != null) { await this.o.objects.delete(key); removedDeleted++; freed += size; }
        }
      }
    }
    return { derivativesDropped: dropped, objectsDeleted: deleted, removedOriginalsDeleted: removedDeleted, bytesFreed: freed };
  }
}

export type ServeDecision = { ok: true } | { ok: false; status: 400 | 403 | 404 | 410; code: string; reason: string };

/**
 * May this viewer get this variant of this entry? (checked when a URL is signed AND again when it is fetched)
 *  - only published entries are served; removed answers 410 (takedown is immediate), held/pending 404
 *  - sound/music: never the raw file, only preview-ogg@1
 *  - proprietary-nxeon: never an original; any preview only when the owner cleared the library
 *  - the plan gate + licence tiers of the catalog tools (sounds Saka+, visuals the top plan; free/Katara nothing)
 */
export function canServe(e: CatalogEntry, variant: Variant, viewer: { signedIn: boolean; plan: unknown }, flags: { proprietaryCleared: boolean }): ServeDecision {
  if (!viewer.signedIn) return { ok: false, status: 403, code: "sign_in", reason: "Sign in to use the asset library." };
  if (e.status === "removed") return { ok: false, status: 410, code: "removed", reason: "This asset was removed from the library." };
  if (e.status !== "published") return { ok: false, status: 404, code: "not_found", reason: "Not found." };
  const audio = e.kind === "sound" || e.kind === "music";
  if (audio && variant !== "preview-ogg@1") return { ok: false, status: 403, code: "raw_audio", reason: "Library audio is only served as a preview; builds use it through the render path." };
  if (e.licence.tier === "proprietary-nxeon") {
