    if (!relPath || relPath.includes("\0") || path.isAbsolute(relPath) || relPath.split(/[\\/]/).includes("..")) return [];
    try {
      const [real, rootReal] = await Promise.all([fsp.realpath(path.resolve(this.root, relPath)), fsp.realpath(this.root)]);
      if (!real.startsWith(rootReal + path.sep)) return [];
      return (await fsp.readdir(real, { withFileTypes: true })).filter((d) => d.isFile()).map((d) => d.name).sort();
    } catch { return []; }
  }
